const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const steps = [{"step": "classify", "node": "Classify", "model": "gpt-4.1-mini"}, {"step": "answer", "node": "Answer", "model": "gpt-4.1-mini"}, {"step": "review", "node": "Review", "model": "gpt-4.1-mini"}];
const by_step = {};
let prompt_tokens = 0, completion_tokens = 0, llm_calls = 0;
for (const s of steps) {
  if (!ran(s.node)) continue;
  const u = $(s.node).first().json.usage ?? {};
  const row = { model: s.model, prompt_tokens: u.prompt_tokens ?? 0, completion_tokens: u.completion_tokens ?? 0 };
  by_step[s.step] = row;
  prompt_tokens += row.prompt_tokens; completion_tokens += row.completion_tokens; llm_calls += 1;
}
const results = $('Search FAQ').first().json.results ?? [];
const answer = String($('Review').first().json.choices[0].message.content ?? '').trim();
const result = { route: '자동 답변', answer, sources: results.map((r) => r.id), llm_calls,
  usage: { prompt_tokens, completion_tokens, by_step } };
return [{ json: result }];
